                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Capa do Curso (Imagem Principal)</label>
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
                      <div className="lg:col-span-2 space-y-4">
