            <div className="flex items-center justify-between"><div className="flex items-center gap-3 text-slate-900"><Database size={20} className="text-indigo-600" /><h2 className="font-bold">Quota de Armazenamento</h2></div><span className={`text-xs font-black uppercase tracking-widest ${isCritical ? 'text-red-600' : isWarning ? 'text-amber-600' : 'text-slate-500'}`}>{formatFileSize(currentUsedStorage)} / 5 GB Utilizados</span></div>
            <div className="h-3 w-full bg-slate-100 rounded-full overflow-hidden border border-slate-50 shadow-inner"><div className={`h-full transition-all duration-1000 ${isCritical ? 'bg-red-500' : isWarning ? 'bg-amber-500' : 'bg-emerald-500'}`} style={{ width: `${Math.min(storagePercentage, 100)}%` }} /></div>
          </div>
