        </div>
      );
    }

    return (
      <div className="space-y-6 animate-in fade-in duration-500"><header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Portal do Professor</h1><p className="text-slate-500 text-sm">Gestão educacional de cursos EAD.</p></div><button onClick={() => { setIsEditingCourse(false); setEditingCourseId(null); setCourseForm({ nome: '', tema: '', categoria: 'Teologia', nivelDificuldade: 'Iniciante', professorResponsavel: user.displayName || '', professorBio: '', professorPhotoURL: '', descricaoLonga: '', capaUrl: '', cargaHoraria: '', materialGlobalUrl: '', publicoAlvo: 'Geral', geraCertificado: false }); setShowCourseModal(true); setActiveModalTab('geral'); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Curso</button></header><div className="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-6 gap-4">{loading ? (<div className="col-span-full py-20 flex justify-center"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>) : myCourses.map(course => (<div key={course.id} onClick={() => openCourseDetail(course)} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-indigo-200 group cursor-pointer flex flex-col relative"><div className="absolute top-2 right-2 z-50"><button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === course.id ? null : course.id); }} className="p-1.5 bg-white/90 backdrop-blur-sm rounded-lg border border-slate-200 text-slate-500 shadow-sm"><MoreVertical size={14} /></button>{openMenuId === course.id && (<div className="absolute right-0 mt-1 w-32 bg-white rounded-xl shadow-2xl border border-slate-100 z-50 overflow-hidden text-[10px] font-bold"><button onClick={(e) => { e.stopPropagation(); handleEditCourseInfo(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Edit size={12} /> Editar</button><button onClick={(e) => { e.stopPropagation(); handleDuplicateCourse(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Copy size={12} /> Copiar</button><button onClick={(e) => { e.stopPropagation(); handleDeleteCourse(course.id); }} className="w-full px-3 py-2 text-left hover:bg-red-50 text-red-500 flex items-center gap-2"><Trash2 size={12} /> Apagar</button></div>)}</div><div className="h-24 overflow-hidden bg-slate-100 relative">{course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={32} /></div>}</div><div className="p-3 flex-1 flex flex-col"><h3 className="font-bold text-slate-900 text-xs mb-1 group-hover:text-indigo-600 transition-colors leading-tight line-clamp-2">{course.nome}</h3></div></div>))}</div></div>
    );
  };

  // --- COMPONENTE MATERIAL PICKER (MODAL) ---
  const renderMaterialPicker = () => {
    if (!isMaterialPickerOpen) return null;

    const filteredMaterials = materials.filter(m => {
      const isImg = ['jpg', 'jpeg', 'png', 'webp', 'gif'].includes(m.type.toLowerCase());
      return pickerMode === 'image' ? isImg : !isImg;
    });

    return (
      <div className="fixed inset-0 !z-[10000] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-md animate-in fade-in duration-300">
        <div className="bg-slate-900 w-full max-w-5xl h-[85vh] rounded-[2.5rem] shadow-2xl border border-slate-800 flex flex-col overflow-hidden">
