                  <td className="px-8 py-6">
                    <div className="flex items-center gap-4">
                      <div className="h-10 w-10 rounded-full bg-indigo-500/10 border border-indigo-500/20 flex items-center justify-center text-indigo-400 font-black shadow-inner">
                        {student.name.charAt(0)}
                      </div>
                      <div>
                        <p className="text-sm font-bold text-white leading-none mb-1 group-hover:text-indigo-400 transition-colors">{student.name}</p>
                        <span className={`text-[9px] font-black uppercase tracking-wider px-2 py-0.5 rounded ${
                          student.status === 'Aprovado' ? 'bg-emerald-500/10 text-emerald-400' :
                          student.status === 'Recuperação' ? 'bg-red-500/10 text-red-400' :
                          student.status === 'Pendente' ? 'bg-amber-500/10 text-amber-400' :
                          'bg-indigo-500/10 text-indigo-400'
                        }`}>
                          {student.status}
                        </span>
                      </div>
                    </div>
                  </td>

                  {/* Frequência */}
                  <td className="px-8 py-6 text-sm font-bold text-slate-300">
                    {student.frequency}%
                  </td>

                  {/* Desempenho */}
                  <td className="px-8 py-6">
                    <div className="flex gap-2">
                      <div className={`w-10 h-8 flex items-center justify-center rounded-lg border text-xs font-black ${student.exam1 ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-900 border-slate-800 text-slate-700'}`}>
                        {student.exam1?.toFixed(1) || '-'}
                      </div>
                      <div className={`w-10 h-8 flex items-center justify-center rounded-lg border text-xs font-black ${student.exam2 ? 'bg-slate-800 border-slate-700 text-white' : 'bg-slate-900 border-slate-800 text-slate-700'}`}>
                        {student.exam2?.toFixed(1) || '-'}
                      </div>
                    </div>
                  </td>

                  {/* Progresso */}
                  <td className="px-8 py-6">
                    <div className="w-full max-w-[150px]">
                      <div className="flex justify-between items-center mb-1.5">
                        <span className="text-[10px] font-black text-slate-500">{student.progress}%</span>
                      </div>
                      <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden">
                        <div 
                          className="h-full bg-gradient-to-r from-indigo-600 to-indigo-400 rounded-full transition-all duration-1000" 
                          style={{ width: `${student.progress}%` }} 
                        />
                      </div>
                    </div>
                  </td>

                  {/* Ações */}
                  <td className="px-8 py-6 text-right">
                    <button className="inline-flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-indigo-600 text-slate-300 hover:text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all">
                      <Eye size={14} /> Ver Histórico
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        {filteredStudents.length === 0 && (
          <div className="p-20 text-center text-slate-500 italic">Nenhum aluno encontrado nesta busca.</div>
        )}
      </div>
    </div>
  );
};

export default DiaryTab;

