                          <div className="flex flex-col items-center gap-2 opacity-20">
                            <Clapperboard size={48} />
                            <span className="text-[9px] font-black uppercase">Preview da Capa</span>
                          </div>
                        )}
                      </div>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Material de Apoio Global (Link)</label>
                    <div className="flex gap-2">
                      <div className="relative flex-1">
                        <Globe className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500" size={18} />
                        <input value={courseForm.materialGlobalUrl} onChange={e => setCourseForm({...courseForm, materialGlobalUrl: e.target.value})} placeholder="https://drive.google.com/..." className="w-full pl-12 pr-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-sm text-white focus:ring-2 focus:ring-indigo-500 outline-none" />
                      </div>
                      <button type="button" onClick={() => handleOpenMaterialPicker('document', (url) => setCourseForm(prev => ({...prev, materialGlobalUrl: url})))} className="px-4 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 transition-all shadow-lg flex items-center gap-2"><Library size={20} /></button>
                    </div>
                    <p className="text-[10px] text-slate-500 mt-2 px-1">Este link ficará visível na página inicial do curso para download rápido.</p>
                  </div>
                </div>
              )}

              <footer className="pt-8 flex gap-4 border-t border-slate-800 sticky bottom-0 bg-slate-900 mt-auto">
                <button type="button" onClick={handleCloseCourseModal} className="flex-1 py-5 border border-slate-700 text-slate-400 rounded-2xl font-bold uppercase text-xs tracking-[0.2em] hover:bg-slate-800 transition-all">Descartar</button>
                <button type="submit" disabled={loading} className="flex-[2] bg-indigo-600 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-indigo-900/40 hover:bg-indigo-500 transition-all active:scale-95 disabled:opacity-50">
                  {loading ? 'Salvando...' : (isEditingCourse ? 'Atualizar Matriz' : 'Publicar Matriz')}
                </button>
              </footer>
            </form>
          </div>
        </div>
      )}
      {renderMainContent()}
    </div>
  );
};

