                    <div className="space-y-2"><label className="text-[10px] text-slate-500">Ao final de qual Módulo esta prova aparecerá?</label><select required value={examForm.linkedModuleId} onChange={e => setExamForm({...examForm, linkedModuleId: e.target.value})} className="w-full px-5 py-4 bg-slate-800 border border-slate-700 rounded-2xl text-white"><option value="">Selecione o módulo...</option>{modules.map(m => (<option key={m.id} value={m.id}>Módulo {m.ordem}: {m.nome}</option>))}</select></div>
