              <div className="space-y-6">
                <div className="flex items-center justify-between border-b border-slate-800 pb-4"><h3 className="font-black text-indigo-400 text-xs uppercase tracking-[0.3em]">Questões Disponíveis</h3><button type="button" onClick={handleAddQuestion} className="flex items-center gap-2 text-indigo-400 hover:text-indigo-300 transition-colors font-bold text-xs uppercase"><Plus size={16} /> Adicionar Pergunta</button></div>
