                  </div>
                  {lessonForm.materialUrl && (<div className="px-4 py-2 bg-emerald-50 border border-emerald-100 rounded-xl flex items-center gap-3"><CheckCircle size={14} className="text-emerald-500" /><span className="text-[10px] font-bold text-emerald-700 uppercase tracking-tight truncate">Arquivo vinculado</span></div>)}
