                    </div>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Ementa / Descrição Longa</label>
                    <textarea required value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} placeholder="Descreva os objetivos, módulos e o que o aluno irá aprender..." className="w-full px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-sm text-white focus:ring-2 focus:ring-indigo-500 outline-none min-h-[160px] resize-none"></textarea>
                  </div>

                  <div className="flex items-center gap-8 p-6 bg-slate-800/30 rounded-3xl border border-slate-800">
