                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Biografia / Resumo Profissional</label>
                    <textarea required value={courseForm.professorBio} onChange={e => setCourseForm({...courseForm, professorBio: e.target.value})} placeholder="Descreva as qualificações e trajetória do professor..." className="w-full px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-sm text-white focus:ring-2 focus:ring-indigo-500 outline-none min-h-[160px] resize-none"></textarea>
                  </div>
                </div>
              )}

              {/* ABA 3: MÍDIAS E LINKS */}
              {activeModalTab === 'midia' && (
                <div className="space-y-8 animate-in slide-in-from-left-4 duration-300">
                  <div className="space-y-4">
                    <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">Capa do Curso (Imagem Principal)</label>
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
                      <div className="lg:col-span-2 space-y-4">
                        <div className="flex gap-2">
                          <input required value={courseForm.capaUrl} onChange={e => setCourseForm({...courseForm, capaUrl: e.target.value})} placeholder="URL da imagem de capa..." className="flex-1 px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-sm text-white focus:ring-2 focus:ring-indigo-500 outline-none" />
                          <button type="button" onClick={() => handleOpenMaterialPicker('image', (url) => setCourseForm(prev => ({...prev, capaUrl: url})))} className="px-4 bg-indigo-600 text-white rounded-2xl hover:bg-indigo-700 transition-all shadow-lg flex items-center gap-2"><Library size={20} /></button>
                        </div>
                        <p className="text-[10px] text-slate-500 italic leading-relaxed">Recomenda-se o uso de imagens com proporção 16:9 para melhor visualização nos cards de curso.</p>
                      </div>
                      <div className="aspect-video bg-slate-800 rounded-3xl border border-slate-700 flex flex-col items-center justify-center overflow-hidden relative shadow-2xl">
