              </div>
              <button 
                className="flex items-center gap-3 bg-indigo-600 hover:bg-indigo-500 text-white px-8 py-4 rounded-2xl text-xs font-black uppercase tracking-[0.2em] shadow-2xl shadow-indigo-900/40 transition-all active:scale-95"
                onClick={() => window.print()}
              >
                <Download size={18} /> Exportar Relatório Acadêmico
              </button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

