                    <input placeholder="Ex: Masterclass de Exegese" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Data e Horário</label>
                    <input type="datetime-local" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                  </div>
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Link da Transmissão (YouTube/Zoom/Meet)</label>
                  <input placeholder="https://..." className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" />
                </div>
                <div className="pt-4 flex gap-4">
                  <button className="flex-1 bg-slate-900 text-white py-4 rounded-2xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-slate-800 transition-all active:scale-95 flex items-center justify-center gap-2"><Bell size={16} /> Notificar Alunos</button>
                  <button className="flex-[2] bg-indigo-600 text-white py-4 rounded-2xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-indigo-500 transition-all active:scale-95">Publicar Link na Sala</button>
                </div>
              </div>
            </div>

            <div className="bg-slate-900 p-8 rounded-[2.5rem] border border-slate-800 shadow-2xl text-white space-y-6">
              <h3 className="text-[10px] font-black text-indigo-400 uppercase tracking-widest flex items-center gap-3"><History size={16} /> Encontros Anteriores</h3>
              <div className="space-y-4">
                {[
                  { title: 'Introdução ao Grego', date: '10/05/24', views: '45' },
                  { title: 'Mentoria Ministerial', date: '03/05/24', views: '28' },
                  { title: 'Dúvidas Módulo 1', date: '28/04/24', views: '62' }
                ].map((live, i) => (
                  <div key={i} className="p-4 bg-slate-800/50 rounded-2xl border border-slate-800 group hover:border-indigo-500/50 transition-all flex items-center justify-between">
                    <div>
                      <p className="text-xs font-bold leading-none mb-1">{live.title}</p>
                      <p className="text-[10px] text-slate-500 font-medium">{live.date} • {live.views} visualizações</p>
                    </div>
                    <button className="p-2 text-slate-500 hover:text-white group-hover:text-indigo-400 transition-all"><ExternalLink size={16} /></button>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      );
    }

    if (activeSub === 'feedback') {
      const avgRating = feedbacks.reduce((acc, f) => acc + f.rating, 0) / feedbacks.length;
      return (
        <div className="space-y-8 animate-in fade-in duration-500">
          <header>
            <h1 className="text-2xl font-bold text-slate-900 tracking-tight">Dashboard de Reputação</h1>
            <p className="text-slate-500 text-sm">Monitoramento de qualidade e satisfação discente.</p>
          </header>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="bg-slate-900 p-8 rounded-[2rem] border border-slate-800 shadow-xl flex flex-col justify-center items-center text-center space-y-4">
              <div className="p-4 bg-indigo-600/10 text-indigo-400 rounded-3xl border border-indigo-600/20">
                <Star size={40} fill="currentColor" className="text-amber-400" />
              </div>
              <div>
                <h3 className="text-4xl font-black text-white">{avgRating.toFixed(1)}</h3>
                <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mt-1">Nota Geral de Ensino</p>
              </div>
              <div className="flex gap-1">
                {[1, 2, 3, 4, 5].map((s) => (
                  <Star key={s} size={16} fill={s <= Math.round(avgRating) ? "#fbbf24" : "none"} className={s <= Math.round(avgRating) ? "text-amber-400" : "text-slate-700"} />
                ))}
              </div>
              <span className="px-4 py-1.5 bg-slate-800 text-slate-400 rounded-full text-[10px] font-black uppercase tracking-tighter">Baseado em {feedbacks.length} avaliações</span>
            </div>
          </div>
        </div>
      );
    }

    if (activeSub === 'avaliacao') {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
            <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Gestão de Avaliações</h1><p className="text-slate-500 text-sm">Criação de provas e testes de proficiência.</p></div>
            <button onClick={() => { setIsEditingExam(false); setExamForm({ title: '', courseId: '', passingGrade: 7.0, questions: [{ id: '1', text: '', options: ['', '', '', ''], correctOptionIndex: 0 }], type: 'activity' }); setIsExamModalOpen(true); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><PlusCircle size={18} /> Nova Avaliação</button>
          </header>
          {exams.length === 0 ? (<div className="bg-white p-24 rounded-3xl border border-dashed border-slate-200 text-center flex flex-col items-center justify-center animate-in zoom-in-95"><div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6 text-slate-300"><ClipboardCheck size={40} /></div><h3 className="font-bold text-slate-900 text-lg">Nenhuma prova cadastrada</h3></div>) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {exams.map((exam) => (
                <div key={exam.id} className="group bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/40 transition-all relative">
                  <div className="flex justify-between items-start mb-4">
                    <div className={`p-3 rounded-2xl ${exam.type === 'evaluation' ? 'bg-orange-500/10 text-orange-400' : 'bg-blue-500/10 text-blue-400'}`}>
                      {exam.type === 'evaluation' ? <Star size={24} /> : <PencilLine size={24} />}
                    </div>
                  </div>
                  <h3 className="text-white font-bold text-lg mb-1 leading-tight">{exam.title}</h3>
                </div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'materiais') {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm space-y-4">
            <div className="flex items-center justify-between"><div className="flex items-center gap-3 text-slate-900"><Database size={20} className="text-indigo-600" /><h2 className="font-bold">Quota de Armazenamento</h2></div><span className={`text-xs font-black uppercase tracking-widest ${storagePercentage > 70 ? 'text-amber-600' : 'text-slate-500'}`}>{formatFileSize(currentUsedStorage)} / 5 GB Utilizados</span></div>
            <div className="h-3 w-full bg-slate-100 rounded-full overflow-hidden border border-slate-50 shadow-inner"><div className={`h-full transition-all duration-1000 ${storagePercentage > 70 ? 'bg-amber-500' : 'bg-emerald-500'}`} style={{ width: `${Math.min(storagePercentage, 100)}%` }} /></div>
