          <header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Materiais</h1><p className="text-slate-500 text-sm">Gerenciamento centralizado de mídia pedagógica.</p></div><button onClick={() => materialInputRef.current?.click()} className={`flex items-center gap-2 px-5 py-3 rounded-xl text-sm font-bold shadow-lg bg-slate-900 text-white hover:bg-slate-800 active:scale-95`}><CloudUpload size={18} /> Upload de Arquivo</button>            <input type="file" ref={materialInputRef} className="hidden" multiple onChange={handleMaterialUpload} accept=".pdf,.docx,.xlsx,.pptx,.jpg,.jpeg,.png" />
          </header>
          {materials.length === 0 ? (<div className="bg-white p-24 rounded-3xl border border-dashed border-slate-200 text-center flex flex-col items-center justify-center animate-in zoom-in-95"><div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center mb-6 text-slate-300"><CloudUpload size={40} /></div><h3 className="font-bold text-slate-900 text-lg">Biblioteca Vazia</h3></div>) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {materials.map((file) => (
                <div key={file.id} className="group relative bg-slate-900 rounded-3xl border border-slate-800 p-5 shadow-xl hover:border-indigo-500/40 transition-all hover:shadow-indigo-500/10 animate-in fade-in slide-in-from-bottom-4 duration-300"><div className="flex flex-col h-full"><div className="flex justify-between items-start mb-6"><div className="p-3 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform shadow-lg">{getFileIcon(file.type)}</div></div><div className="flex-1 min-w-0"><h3 className="text-white font-bold text-sm truncate leading-tight mb-1">{file.name}</h3></div></div></div>
              ))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'modulos') {
      const allModules = Object.values(allModulesGrouped).flatMap((group: { course: Course; modules: Module[] }) => group.modules.map(m => ({ ...m, courseName: group.course.nome }))).sort((a, b) => a.ordem - b.ordem);
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex flex-col sm:flex-row items-center justify-between gap-4"><div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Módulos</h1><p className="text-slate-500 text-sm">Matriz integrada de cursos.</p></div><button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Módulo</button></header>
          {loading ? (<div className="flex items-center justify-center p-20"><div className="h-10 w-10 animate-spin rounded-full border-4 border-indigo-600 border-t-transparent"></div></div>) : (
            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
              {allModules.map((mod: any) => (<div key={mod.id} className="group bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl hover:border-indigo-500/50 transition-all"><div className="flex flex-col h-full"><div className="flex justify-between items-start mb-4"><div className="px-3 py-1 bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-[9px] font-black uppercase tracking-widest rounded-full">{mod.courseName}</div></div><h3 className="text-white font-bold text-lg mb-2">{mod.ordem.toString().padStart(2, '0')}. {mod.nome}</h3></div></div>))}
            </div>
          )}
        </div>
      );
    }

    if (activeSub === 'cursos' && selectedCourse) {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex items-center justify-between gap-4">
            <div className="flex items-center gap-4">
              <button onClick={() => setSelectedCourse(null)} className="h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button>
              <div>
                <h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1>
                <div className="flex items-center gap-3 mt-1">
                  <span className="text-slate-500 text-sm">{selectedCourse.tema}</span>
                </div>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <button 
                onClick={() => setIsDiaryModalOpen(true)}
                className="flex items-center gap-2 bg-slate-900 text-white px-5 py-2.5 rounded-xl text-sm font-bold shadow-lg hover:bg-slate-800 transition-all"
              >
                <Calendar size={18} /> Ver Diário de Classe
              </button>
              <button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Módulo</button>
            </div>
          </header>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 space-y-4">
              <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-slate-100 bg-slate-50/50"><h2 className="text-xs font-bold text-slate-800 uppercase tracking-widest">Matriz Curricular</h2></div>
                <div className="p-4 space-y-4">
                  {modules.map((mod) => (
                    <div key={mod.id} className="border border-slate-100 rounded-xl group bg-slate-50/20">
                      <div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between bg-white">
                        <h3 className="font-bold text-slate-800 text-sm">Módulo {mod.ordem}: {mod.nome}</h3>
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <button onClick={() => { setActiveModuleId(mod.id); setIsEditingLesson(false); setEditingLessonId(null); setLessonForm({titulo:'', descricao:'', videoUrl:'', materialUrl:''}); setShowLessonModal(true); }} className="p-1.5 text-indigo-600 hover:bg-indigo-50 rounded-lg"><Plus size={18} /></button>
                          <button onClick={() => handleEditModule(mod)} className="p-1.5 text-slate-400 hover:bg-slate-50 rounded-lg"><Edit size={18} /></button>
                          <button onClick={() => handleDeleteModule(selectedCourse.id, mod.id)} className="p-1.5 text-red-400 hover:bg-red-50 rounded-lg"><Trash2 size={18} /></button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      );
    }

    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex flex-col sm:flex-row items-center justify-between gap-4">
          <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Portal do Professor</h1><p className="text-slate-500 text-sm">Gestão educacional de cursos EAD.</p></div>
          <button onClick={() => { setIsEditingCourse(false); setEditingCourseId(null); setCourseForm({ nome: '', tema: '', categoria: 'Teologia', nivelDificuldade: 'Iniciante', professorResponsavel: user.displayName || '', professorBio: '', professorPhotoURL: '', descricaoLonga: '', capaUrl: '', cargaHoraria: '', materialGlobalUrl: '', publicoAlvo: 'Geral', geraCertificado: false }); setShowCourseModal(true); setActiveModalTab('geral'); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Curso</button>
        </header>
        <div className="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-6 gap-4">
          {loading ? (
            <div className="col-span-full py-20 flex justify-center"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent"></div></div>
          ) : myCourses.map(course => (
            <div key={course.id} onClick={() => openCourseDetail(course)} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-indigo-200 group cursor-pointer flex flex-col relative">
              <div className="absolute top-2 right-2 z-50">
                <button onClick={(e) => { e.stopPropagation(); setOpenMenuId(openMenuId === course.id ? null : course.id); }} className="p-1.5 bg-white/90 backdrop-blur-sm rounded-lg border border-slate-200 text-slate-500 shadow-sm"><MoreVertical size={14} /></button>
                {openMenuId === course.id && (
                  <div className="absolute right-0 mt-1 w-32 bg-white rounded-xl shadow-2xl border border-slate-100 z-50 overflow-hidden text-[10px] font-bold">
                    <button onClick={(e) => { e.stopPropagation(); handleEditCourseInfo(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Edit size={12} /> Editar</button>
                    <button onClick={(e) => { e.stopPropagation(); handleDuplicateCourse(course); }} className="w-full px-3 py-2 text-left hover:bg-slate-50 flex items-center gap-2"><Copy size={12} /> Copiar</button>
                    <button onClick={(e) => { e.stopPropagation(); handleDeleteCourse(course.id); }} className="w-full px-3 py-2 text-left hover:bg-red-50 text-red-500 flex items-center gap-2"><Trash2 size={12} /> Apagar</button>
                  </div>
                )}
              </div>
              <div className="h-24 overflow-hidden bg-slate-100 relative">{course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={32} /></div>}</div>
              <div className="p-3 flex-1 flex flex-col"><h3 className="font-bold text-slate-900 text-xs mb-1 group-hover:text-indigo-600 transition-colors leading-tight line-clamp-2">{course.nome}</h3></div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  return (
    <div className="relative">
      {renderMainContent()}

      {/* MODAL DIÁRIO DE CLASSE (FLUTUANTE) */}
      {isDiaryModalOpen && selectedCourse && (
        <div className="fixed inset-0 !z-[10001] flex items-center justify-center p-8 bg-slate-950/95 backdrop-blur-xl animate-in fade-in duration-500">
          <div className="bg-slate-900 w-[90vw] h-[90vh] rounded-[3rem] shadow-2xl border border-slate-800 flex flex-col overflow-hidden animate-in zoom-in-95 duration-500">
            <header className="px-10 py-8 border-b border-slate-800 flex items-center justify-between">
              <div className="flex items-center gap-6">
                <div className="p-4 bg-indigo-600 text-white rounded-[1.5rem] shadow-xl shadow-indigo-900/40"><Calendar size={32} /></div>
                <div>
                  <h2 className="text-3xl font-black text-white tracking-tight">Diário de Classe Digital</h2>
                  <p className="text-indigo-400 text-xs font-black uppercase tracking-[0.3em] mt-1">{selectedCourse.nome}</p>
                </div>
              </div>
              <button onClick={() => setIsDiaryModalOpen(false)} className="h-14 w-14 bg-slate-800 hover:bg-red-600 text-slate-400 hover:text-white rounded-2xl transition-all flex items-center justify-center"><X size={28} /></button>
            </header>
            <div className="flex-1 overflow-auto p-10">
              <table className="w-full text-left border-collapse min-w-[800px]">
                <thead className="sticky top-0 bg-slate-900 text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] border-b border-slate-800">
                  <tr>
                    <th className="px-6 py-4">Estudante</th>
                    <th className="px-6 py-4">Progresso Acadêmico</th>
                    <th className="px-6 py-4">Último Acesso</th>
                    <th className="px-6 py-4">Notas Atividades</th>
                    <th className="px-6 py-4">Avaliação Final</th>
                    <th className="px-6 py-4 text-right">Status</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-800/50">
                  {mockDiaryStudents.map((student) => (
                    <tr key={student.id} className="hover:bg-indigo-500/5 transition-colors group">
                      <td className="px-6 py-6">
                        <div className="flex items-center gap-4">
                          <div className="h-12 w-12 rounded-2xl bg-slate-800 border border-slate-700 flex items-center justify-center text-indigo-400 font-bold text-lg shadow-inner group-hover:scale-110 transition-transform">{student.name.charAt(0)}</div>
                          <div><p className="text-sm font-bold text-white leading-none mb-1">{student.name}</p><p className="text-[10px] text-slate-500 font-medium">ID: {student.id.padStart(5, '0')}</p></div>
                        </div>
                      </td>
                      <td className="px-6 py-6">
                        <div className="w-40">
                          <div className="flex justify-between items-center mb-1.5"><span className="text-[10px] font-black text-indigo-400">{student.progress}%</span></div>
                          <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden"><div className="h-full bg-gradient-to-r from-indigo-600 to-indigo-400 rounded-full transition-all duration-1000" style={{ width: `${student.progress}%` }} /></div>
                        </div>
                      </td>
                      <td className="px-6 py-6 text-xs text-slate-400 font-medium"><Clock size={14} className="text-slate-600 mr-2 inline" />{student.lastAccess}</td>
                      <td className="px-6 py-6"><span className="text-xs font-mono font-bold text-slate-300 bg-slate-800 px-2 py-1 rounded-lg border border-slate-700">{student.quizGrades}</span></td>
                      <td className="px-6 py-6"><span className={`text-sm font-black ${student.finalGrade && student.finalGrade >= 7 ? 'text-emerald-400' : 'text-orange-400'}`}>{student.finalGrade?.toFixed(1) || 'Pendente'}</span></td>
                      <td className="px-6 py-6 text-right"><span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-wider ${student.progress === 100 ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20' : 'bg-indigo-500/10 text-indigo-400 border border-indigo-500/20'}`}>{student.progress === 100 ? 'Graduado' : 'Em Trilha'}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* MODAIS EXISTENTES */}
      {isModuleModalOpen && (
        <div className="fixed inset-0 !z-[9999] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl p-6 border border-slate-100">
            <h3 className="font-bold text-slate-900 mb-4">{currentEditingModule ? 'Editar Módulo' : 'Configurar Novo Módulo'}</h3>
            <form onSubmit={handleSaveModule} className="space-y-5">
              <input required autoFocus value={moduleForm.nome} onChange={e => setModuleForm({...moduleForm, nome: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border rounded-xl text-sm" />
              <div className="flex gap-3"><button type="button" onClick={() => setIsModuleModalOpen(false)} className="flex-1 px-4 py-2.5 border rounded-xl font-bold text-sm">Cancelar</button><button type="submit" className="flex-1 bg-indigo-600 text-white py-2.5 rounded-xl font-bold text-sm shadow-lg">Salvar</button></div>
            </form>
          </div>
        </div>
      )}

      {showLessonModal && (
        <div className="fixed inset-0 !z-[9998] flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm animate-in fade-in">
          <div className="bg-white w-full max-w-xl rounded-3xl shadow-2xl p-8 animate-in zoom-in-95 border border-slate-100">
            <h3 className="font-bold text-slate-900 text-xl mb-6 flex items-center gap-3"><PlusCircle size={24} className="text-indigo-600" /> {isEditingLesson ? 'Editar Aula' : 'Publicar Nova Unidade'}</h3>
            <form onSubmit={handleSaveLesson} className="space-y-5">
              <input required value={lessonForm.titulo} onChange={e => setLessonForm({...lessonForm, titulo: e.target.value})} placeholder="Título da Aula" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500" />
              <div className="flex gap-4 pt-4"><button type="button" onClick={() => setShowLessonModal(false)} className="flex-1 py-4 border border-slate-200 text-slate-500 rounded-2xl font-bold text-sm hover:bg-slate-50">Cancelar</button><button type="submit" className="flex-[2] bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm shadow-xl active:scale-95">Salvar Alterações</button></div>
            </form>
          </div>
        </div>
      )}

      {showCourseModal && (
        <div className="fixed inset-0 !z-[9997] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-slate-900 w-full max-w-4xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 flex flex-col max-h-[90vh] border border-slate-800">
            <div className="p-8 pb-0 border-b border-slate-800 flex flex-col gap-6">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <div className="bg-indigo-600 p-3 rounded-2xl text-white shadow-xl shadow-indigo-900/20"><GraduationCap size={28} /></div>
                  <div><h3 className="font-bold text-white text-2xl tracking-tight">{isEditingCourse ? 'Refinar Matriz Acadêmica' : 'Projetar Novo Curso'}</h3></div>
                </div>
                <button onClick={handleCloseCourseModal} className="text-slate-500 hover:text-white p-2 transition-colors"><X size={32} /></button>
              </div>
              <div className="flex gap-1 pb-4">
                {[{ id: 'geral', label: 'Dados Gerais' }, { id: 'docente', label: 'Corpo Docente' }, { id: 'midia', label: 'Mídias e Links' }].map((tab) => (
                  <button key={tab.id} type="button" onClick={() => setActiveModalTab(tab.id as any)} className={`px-6 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${activeModalTab === tab.id ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-800'}`}>{tab.label}</button>
                ))}
              </div>
            </div>
            <form onSubmit={handleSaveCourse} className="flex-1 overflow-y-auto p-10 pt-8 space-y-8 scroll-smooth">
              {activeModalTab === 'geral' && (
                <div className="space-y-6">
                  <input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Título do Curso" className="w-full px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-white focus:ring-2 focus:ring-indigo-500 outline-none" />
                  <textarea required value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} placeholder="Ementa / Descrição Longa" className="w-full px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-white focus:ring-2 focus:ring-indigo-500 outline-none min-h-[160px] resize-none"></textarea>
                </div>
              )}
              <footer className="pt-8 flex gap-4 border-t border-slate-800 sticky bottom-0 bg-slate-900 mt-auto">
                <button type="button" onClick={handleCloseCourseModal} className="flex-1 py-5 border border-slate-700 text-slate-400 rounded-2xl font-bold uppercase text-xs tracking-[0.2em] hover:bg-slate-800 transition-all">Descartar</button>
                <button type="submit" disabled={loading} className="flex-[2] bg-indigo-600 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-indigo-900/40 hover:bg-indigo-500 transition-all active:scale-95 disabled:opacity-50">{loading ? 'Salvando...' : 'Publicar Matriz'}</button>
              </footer>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;

