      const fetched: Course[] = [];
      querySnapshot.forEach((doc) => { fetched.push({ id: doc.id, ...doc.data() } as Course); });
      setMyCourses(fetched);
    } catch (error) { console.error(error); } finally { setLoading(false); }
  };

