    if (lowerUrl.includes('youtube.com') || lowerUrl.includes('youtu.be') || lowerUrl.includes('vimeo')) return <Video size={32} className="text-red-500" />;
    if (lowerUrl.includes('.jpg') || lowerUrl.includes('.png') || lowerUrl.includes('.webp')) return <FileImage size={32} className="text-pink-500" />;
    if (lowerUrl.includes('.pdf')) return <FileText size={32} className="text-red-600" />;
    if (lowerUrl.includes('.xlsx') || lowerUrl.includes('.csv')) return <FileSpreadsheet size={32} className="text-emerald-500" />;
