                      onChange={e => setNewMaterialLink({...newMaterialLink, url: e.target.value})}
                      placeholder="https://drive.google.com/..." 
                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all" 
                   />
                </div>
                <button type="submit" className="px-8 h-12 bg-slate-900 text-white rounded-2xl text-xs font-black uppercase tracking-widest shadow-xl hover:bg-slate-800 transition-all active:scale-95">Vincular Link</button>
             </form>
             <p className="text-[10px] text-slate-400 italic">O sistema identificará automaticamente o ícone de serviço (Drive, Dropbox ou Vídeo) com base na URL fornecida.</p>
          </div>

          <header className="flex justify-between items-center">
            <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Materiais</h1><p className="text-slate-500 text-sm">Gerenciamento centralizado de mídia pedagógica.</p></div>
          </header>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
            {materials.length === 0 ? (
              <div className="col-span-full py-20 text-center border-2 border-dashed border-slate-200 rounded-[2rem] bg-white">
                 <Globe size={48} className="mx-auto text-slate-200 mb-4" />
                 <p className="text-slate-400 font-medium">Nenhum material vinculado à biblioteca.</p>
              </div>
            ) : materials.map((file) => (
              <div key={file.id} className="group relative bg-slate-900 rounded-3xl border border-slate-800 p-5 shadow-xl hover:border-indigo-500/40 transition-all hover:shadow-indigo-500/10 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="flex flex-col h-full">
                  <div className="flex justify-between items-start mb-6">
                    {/* ÍCONE INTELIGENTE */}
                    <div className="p-3 bg-slate-800 rounded-2xl group-hover:scale-110 transition-transform shadow-lg">
                      {getLinkIcon(file.url)}
                    </div>
                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <a href={file.url} target="_blank" rel="noopener noreferrer" className="p-2 bg-slate-800 text-slate-300 hover:text-white rounded-lg border border-slate-700">
                        <ExternalLink size={14} />
                      </a>
                    </div>
                  </div>
                  <div className="flex-1 min-w-0">
                    {/* TÍTULO CLICÁVEL */}
                    <a href={file.url} target="_blank" rel="noopener noreferrer" className="text-white font-bold text-sm truncate leading-tight mb-1 block hover:text-indigo-400 transition-colors">
                      {file.name}
                    </a>
                    <div className="flex items-center gap-3">
                      <span className="text-[10px] font-black uppercase text-slate-500 tracking-wider bg-slate-800 px-1.5 py-0.5 rounded">LINK</span>
                      <span className="w-1 h-1 bg-slate-700 rounded-full" />
                      <span className="text-[10px] font-bold text-slate-500">{file.size}</span>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      );
    }

    if (activeSub === 'modulos') {
      const allModules = Object.values(allModulesGrouped).flatMap((group: any) => group.modules.map((m: any) => ({ ...m, courseName: group.course.nome }))).sort((a: any, b: any) => a.ordem - b.ordem);
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex justify-between items-center">
            <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Biblioteca de Módulos</h1></div>
            <button onClick={handleOpenCreateModule} className="bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Módulo</button>
          </header>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {allModules.map((mod: any) => (<div key={mod.id} className="bg-slate-900 rounded-3xl border border-slate-800 p-6 shadow-xl"><div className="px-3 py-1 bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-[9px] font-black uppercase rounded-full w-fit mb-4">{mod.courseName}</div><h3 className="text-white font-bold text-lg">{mod.nome}</h3></div>))}
          </div>
        </div>
      );
    }

    if (activeSub === 'cursos' && selectedCourse) {
      return (
        <div className="space-y-6 animate-in fade-in duration-500">
          <header className="flex items-center justify-between gap-4">
            <div className="flex items-center gap-4">
              <button onClick={() => setSelectedCourse(null)} className="h-10 w-10 bg-white border border-slate-200 hover:bg-slate-50 rounded-xl text-slate-600 shadow-sm flex items-center justify-center"><ArrowLeft size={20} /></button>
              <div><h1 className="text-2xl font-bold text-slate-900 leading-tight">{selectedCourse.nome}</h1><p className="text-slate-500 text-sm">{selectedCourse.tema}</p></div>
            </div>
            <div className="flex items-center gap-3">
              <button onClick={() => setIsDiaryModalOpen(true)} className="flex items-center gap-2 bg-slate-900 text-white px-5 py-2.5 rounded-xl text-sm font-bold shadow-lg hover:bg-slate-800 transition-all"><CalendarIcon size={18} /> Diário de Classe</button>
              <button onClick={handleOpenCreateModule} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Módulo</button>
            </div>
          </header>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 space-y-4">
              <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="px-6 py-4 border-b border-slate-100 bg-slate-50/50 font-bold text-xs uppercase tracking-widest">Matriz Curricular</div>
                <div className="p-4 space-y-4">
                  {modules.map((mod) => (
                    <div key={mod.id} className="border border-slate-100 rounded-xl bg-slate-50/20 p-4">
                      <h3 className="font-bold text-slate-800 text-sm mb-2">Módulo {mod.ordem}: {mod.nome}</h3>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      );
    }

    return (
      <div className="space-y-6 animate-in fade-in duration-500">
        <header className="flex justify-between items-center">
          <div><h1 className="text-2xl font-bold text-slate-900 tracking-tight">Portal do Professor</h1><p className="text-slate-500 text-sm">Gestão educacional de cursos EAD.</p></div>
          <button onClick={() => { setIsEditingCourse(false); setEditingCourseId(null); setCourseForm({ nome: '', tema: '', categoria: 'Teologia', nivelDificuldade: 'Iniciante', professorResponsavel: user.displayName || '', professorBio: '', professorPhotoURL: '', descricaoLonga: '', capaUrl: '', cargaHoraria: '', materialGlobalUrl: '', publicoAlvo: 'Geral', geraCertificado: false }); setShowCourseModal(true); setActiveModalTab('geral'); }} className="flex items-center gap-2 bg-indigo-600 text-white px-5 py-3 rounded-xl text-sm font-bold shadow-lg"><Plus size={18} /> Novo Curso</button>
        </header>
        <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-6 gap-4">
          {loading ? (
            <div className="col-span-full py-20 flex justify-center"><div className="h-6 w-6 animate-spin rounded-full border-2 border-indigo-600 border-t-transparent" /></div>
          ) : myCourses.map(course => (
            <div key={course.id} onClick={() => openCourseDetail(course)} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-indigo-200 cursor-pointer flex flex-col relative group transition-all">
              <div className="h-24 overflow-hidden bg-slate-100">{course.capaUrl ? <img src={course.capaUrl} className="w-full h-full object-cover group-hover:scale-105 transition-all" /> : <div className="h-full flex items-center justify-center text-slate-200"><BookOpen size={32} /></div>}</div>
              <div className="p-3"><h3 className="font-bold text-slate-900 text-xs mb-1 truncate leading-tight">{course.nome}</h3></div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  return (
    <div className="relative">
      {renderMainContent()}

      {/* MODAL DIÁRIO DE CLASSE */}
      {isDiaryModalOpen && selectedCourse && (
        <div className="fixed inset-0 !z-[10001] flex items-center justify-center p-8 bg-slate-950/95 backdrop-blur-xl animate-in fade-in duration-500">
          <div className="bg-slate-900 w-[90vw] h-[90vh] rounded-[3rem] shadow-2xl border border-slate-800 flex flex-col overflow-hidden animate-in zoom-in-95 duration-500">
            <header className="px-10 py-8 border-b border-slate-800 flex items-center justify-between">
              <div className="flex items-center gap-6"><div className="p-4 bg-indigo-600 text-white rounded-[1.5rem] shadow-xl"><CalendarIcon size={32} /></div><div><h2 className="text-3xl font-black text-white tracking-tight">Diário Digital</h2><p className="text-indigo-400 text-xs font-black uppercase mt-1">{selectedCourse.nome}</p></div></div>
              <button onClick={() => setIsDiaryModalOpen(false)} className="h-14 w-14 bg-slate-800 hover:bg-red-600 text-slate-400 hover:text-white rounded-2xl transition-all flex items-center justify-center"><X size={28} /></button>
            </header>
            <div className="flex-1 overflow-auto p-10">
              <table className="w-full text-left border-collapse min-w-[800px]">
                <thead className="sticky top-0 bg-slate-900 text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] border-b border-slate-800">
                  <tr><th className="px-6 py-4">Estudante</th><th className="px-6 py-4">Progresso</th><th className="px-6 py-4">Último Acesso</th><th className="px-6 py-4">Avaliação Final</th><th className="px-6 py-4 text-right">Status</th></tr>
                </thead>
                <tbody className="divide-y divide-slate-800/50">
                  {mockDiaryStudents.map((student) => (
                    <tr key={student.id} className="hover:bg-indigo-500/5 transition-colors group">
                      <td className="px-6 py-6 font-bold text-white text-sm">{student.name}</td>
                      <td className="px-6 py-6 font-black text-indigo-400">{student.progress}%</td>
                      <td className="px-6 py-6 text-xs text-slate-400">{student.lastAccess}</td>
                      <td className="px-6 py-6"><span className={`text-sm font-black ${student.finalGrade && student.finalGrade >= 7 ? 'text-emerald-400' : 'text-orange-400'}`}>{student.finalGrade?.toFixed(1) || 'Pendente'}</span></td>
                      <td className="px-6 py-6 text-right"><span className={`px-4 py-1.5 rounded-full text-[9px] font-black uppercase tracking-wider ${student.progress === 100 ? 'bg-emerald-500/10 text-emerald-400' : 'bg-indigo-500/10 text-indigo-400'}`}>{student.progress === 100 ? 'Graduado' : 'Em Trilha'}</span></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* MODAL CONSTRUTOR DE CURSOS */}
      {showCourseModal && (
        <div className="fixed inset-0 !z-[9997] flex items-center justify-center p-4 bg-slate-950/90 backdrop-blur-xl animate-in fade-in duration-300">
          <div className="bg-slate-900 w-full max-w-4xl rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 flex flex-col max-h-[90vh] border border-slate-800">
            <div className="p-8 pb-0 border-b border-slate-800 flex flex-col gap-6">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-4"><div className="bg-indigo-600 p-3 rounded-2xl text-white shadow-xl"><GraduationCap size={28} /></div><div><h3 className="font-bold text-white text-2xl tracking-tight">{isEditingCourse ? 'Refinar Matriz' : 'Projetar Novo Curso'}</h3></div></div>
                <button onClick={handleCloseCourseModal} className="text-slate-500 hover:text-white p-2 transition-colors"><X size={32} /></button>
              </div>
            </div>
            <form onSubmit={handleSaveCourse} className="flex-1 overflow-y-auto p-10 pt-8 space-y-8">
              <div className="space-y-6">
                <input required value={courseForm.nome} onChange={e => setCourseForm({...courseForm, nome: e.target.value})} placeholder="Título do Curso" className="w-full px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-white focus:ring-2 focus:ring-indigo-500 outline-none" />
                <textarea required value={courseForm.descricaoLonga} onChange={e => setCourseForm({...courseForm, descricaoLonga: e.target.value})} placeholder="Ementa / Descrição Longa" className="w-full px-5 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-white focus:ring-2 focus:ring-indigo-500 outline-none min-h-[160px] resize-none"></textarea>
              </div>
              <footer className="pt-8 flex gap-4 border-t border-slate-800 sticky bottom-0 bg-slate-900 mt-auto">
                <button type="button" onClick={handleCloseCourseModal} className="flex-1 py-5 border border-slate-700 text-slate-400 rounded-2xl font-bold uppercase text-xs tracking-[0.2em] hover:bg-slate-800 transition-all">Descartar</button>
                <button type="submit" disabled={loading} className="flex-[2] bg-indigo-600 text-white py-5 rounded-2xl font-black text-xs uppercase tracking-[0.2em] shadow-2xl shadow-indigo-900/40 hover:bg-indigo-500 transition-all active:scale-95 disabled:opacity-50">{loading ? 'Salvando...' : 'Publicar Matriz'}</button>
              </footer>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProfessorView;
